],"tamanhos":[48620]},{"id":"revalida_2026_1_q015","prova":null,"paths":["questoes/6b6aab8301227b7b17a9b4ff3150fe63.png"],"tamanhos":[54186]},{"id":"revalida_2026_1_q017","prova":null,"paths":["questoes/9f8aeaba7a98c9e73ab33807030c375e.png"],"tamanhos":[15153]},{"id":"revalida_2026_1_q020","prova":null,"paths":["questoes/bb802449cf741ccacad36c251d0b09ff.png"],"tamanhos":[26057]},{"id":"revalida_2026_1_q021","prova":null,"paths":["questoes/ff3ad6b908c707a4af1e13b68e8d6099.png"],"tamanhos":[24951]},{"id":"revalida_2026_1_q029","prova":null,"paths":["questoes/366891f05e5d6f65d02b77ee79888f5f.png"],"tamanhos":[21333]},{"id":"revalida_2026_1_q040","prova":null,"paths":["questoes/c90604bf002ed99338ad863448b85cd3.png"],"tamanhos":[38594]},{"id":"revalida_2026_1_q066","prova":null,"paths":["questoes/86460d370b35c676040adfb2ee1690dd.png"],"tamanhos":[50422]},{"id":"revalida_2026_1_q072","prova":null,"paths":["questoes/cec3377f3c8d0823ed9e6dcb91769e2d.png"],"tamanhos":[45058]},{"id":"revalida_2026_1_q073","prova":null,"paths":["questoes/418a4438925b3a0e6776ed56e256c67b.png"],"tamanhos":[34846]},{"id":"revalida_2026_1_q091","prova":null,"paths":["questoes/999fdc97ab5002430d67119655913244.png"],"tamanhos":[52397]},{"id":"revalida_2026_1_q096","prova":null,"paths":["questoes/0bebdfe070bd8a9687e82d73e33c02f0.png"],"tamanhos":[24990]},{"id":"revalida_2026_2_q022","prova":"revalida-2026-2","paths":["questoes/14a46487aefb6b9660ae082b35dfecf5.png"],"tamanhos":[38052]},{"id":"revalida_2026_2_q023","prova":"revalida-2026-2","paths":["questoes/11b5b649012b8cf0285cbec364057ac8.png"],"tamanhos":[18206]},{"id":"revalida_2026_2_q027","prova":"revalida-2026-2","paths":["questoes/b2e9ac5f505e9a57d9fe789e216295d2.png"],"tamanhos":[17412]},{"id":"revalida_2026_2_q029","prova":"revalida-2026-2","paths":["questoes/7145984642dc03b89ae6c6befb1fd864.png"],"tamanhos":[1217478]},{"id":"revalida_2026_2_q032","prova":"revalida-2026-2","paths":["questoes/a550013a3617f26e23da48678b6cffbd.png"],"tamanhos":[21130]},{"id":"revalida_2026_2_q034","prova":"revalida-2026-2","paths":["questoes/d248491459e1f3b3f7091bbaffc4a7ba.png"],"tamanhos":[29522]},{"id":"revalida_2026_2_q037","prova":"revalida-2026-2","paths":["questoes/b510396ed7dfedebeeecc282f9f951ee.png","questoes/a851e578d01ae7dfff769b1a45cdbab1.png"],"tamanhos":[287653,12840]},{"id":"revalida_2026_2_q052","prova":"revalida-2026-2","paths":["questoes/8a34b7e176469af310728633dd9478eb.png"],"tamanhos":[709238]},{"id":"revalida_2026_2_q053","prova":"revalida-2026-2","paths":["questoes/9c321b22cb87062b963c7e7f4a72430e.png"],"tamanhos":[105159]},{"id":"revalida_2026_2_q059","prova":"revalida-2026-2","paths":["questoes/071a7250697b9b815d70db9e49c70d7d.png"],"tamanhos":[31272]},{"id":"revalida_2026_2_q067","prova":"revalida-2026-2","paths":["questoes/b81541a3310d60f9ae9e42c2e227a07f.png"],"tamanhos":[90337]},{"id":"revalida_2026_2_q075","prova":"revalida-2026-2","paths":["questoes/8188ecf653539b4ba524129b09dafb64.png"],"tamanhos":[445038]},{"id":"revalida_2026_2_q081","prova":"revalida-2026-2","paths":["questoes/254273f7bb768d9758bfaa7c09f68b30.png","questoes/2196c799da8ccca26252e8475246e6e6.png"],"tamanhos":[27305,280915]},{"id":"revalida_2026_2_q082","prova":"revalida-2026-2","paths":["questoes/ccbce72be69dbb1f0d46b47b9ea02928.png"],"tamanhos":[18238]},{"id":"revalida_2026_2_q089","prova":"revalida-2026-2","paths":["questoes/105c8cea1cf49740aa803417cf758fd2.png"],"tamanhos":[1708053]},{"id":"revalida_2026_2_q096","prova":"revalida-2026-2","paths":["questoes/42a947e765107da9edf937462a38c43b.png"],"tamanhos":[13124]}]$conf_imagens$::jsonb) x
),
img_estado as (
  select i.id, coalesce(array(select e ->> 'path' from jsonb_array_elements(q.images) e) = i.paths, false) as ligada,
         case when to_regclass('storage.objects') is null then null else
           (select count(*) from unnest(i.paths) p join storage.objects o on o.bucket_id = 'question-figures' and o.name = p) end as no_deposito,
         cardinality(i.paths) as n
  from imgs i left join public.questions q on q.id = i.id
),
pre as (
  select to_regclass('public.question_figure_files') is not null and to_regprocedure('public.ch_worker_question_figure_confirm(text, text, numeric)') is not null
         and to_regprocedure('public.app_admin_question_history(text, integer, integer)') is not null
         and exists (select 1 from pg_trigger where tgname = 'questions_images_guard') and exists (select 1 from pg_trigger where tgname = 'questions_change_trail') as ok
),
linhas as (
  select 10 as ordem, 'Texto fiel: campos já corrigidos / ainda antigos / com outro texto (de ' || count(*) || ')' as conferencia,
         count(*) filter (where e = 'fiel') || ' / ' || count(*) filter (where e = 'antigo') || ' / ' || count(*) filter (where e in ('outro', 'sem questão')) as resultado
  from estado
  union all
  select 11, '  ' || prova, count(*) filter (where e = 'fiel') || ' fiéis, ' || count(*) filter (where e = 'antigo') || ' antigos, ' || count(*) filter (where e in ('outro', 'sem questão')) || ' outro texto'
  from estado group by prova
  union all
  select 12, '  campo com OUTRO texto (alguém mudou: a parte 2 pula)', string_agg(id || ' ' || campo, ', ') from estado where e in ('outro', 'sem questão') having count(*) > 0
  union all
  select 20, 'Imagens: questões já ligadas (de 77) / arquivos no depósito (de 79)',
         count(*) filter (where ligada) || ' / ' || coalesce(sum(no_deposito)::text, 'sem esquema storage (banco de teste)') from img_estado
  union all
  select 30, 'Prova 2026/2: questões no banco (de 98) / com gabarito PRELIMINAR atual',
         (select count(*) from public.questions where exam_id = 'revalida-2026-2') || ' / ' ||
         (select count(*) from public.question_official_answers o join public.questions q on q.id = o.question_id where q.exam_id = 'revalida-2026-2' and o.is_current and o.answer_status = 'PRELIMINARY')
  union all
  select 40, 'Aviso do gabarito preliminar (parte 1) colado',
         case when pg_get_functiondef('public.practice_correction_view(text, text)'::regprocedure) like '%answer_preliminary%' then 'sim' else 'não' end
  union all
  select 50, 'Análises Stazia publicadas nas questões com texto ainda antigo (saem do ar na parte 2)',
         (select count(*)::text from public.question_analysis a where a.is_current and a.status = 'published' and a.question_id in (select id from estado where e = 'antigo'))
  union all
  select 60, 'Gabarito oficial atual por prova (situação: quantidade) — só registro',
         string_agg(z.exam_id || ' ' || z.s || ': ' || z.n, '; ' order by z.exam_id, z.s)
  from (select q.exam_id, o.answer_status s, count(*) n from public.question_official_answers o join public.questions q on q.id = o.question_id
        where o.is_current group by 1, 2) z
  union all
  select 61, 'Revalida 2020: título da fonte gravada nas questões (o PDF do gabarito diz PRELIMINAR) — só registro',
         (select string_agg(distinct s ->> 'title', ' | ') from public.questions q, jsonb_array_elements(q.sources) s where q.exam_id = 'revalida-2020')
)
select case when not (select ok from pre) then 'FALTA: as migrações 9700/9702 (figuras e histórico das questões) não estão no banco; pare e avise o Claude'
            when exists (select 1 from estado where e in ('outro', 'sem questão')) then 'ATENÇÃO: há campo com texto diferente do esperado (veja a linha 12); o resto pode seguir'
            else 'OK: conferência da carga das provas (' || (select count(*) filter (where e = 'fiel') from estado) || ' de ' || (select count(*) from estado) || ' campos já fiéis; '
                 || (select count(*) filter (where ligada) from img_estado) || ' de 77 questões com imagem ligada; 2026/2 com '
                 || (select count(*) from public.questions where exam_id = 'revalida-2026-2') || ' questões)' end as conferencia,
       null::text as resultado, -1 as ordem
union all
select conferencia, resultado, ordem from linhas
order by ordem;
